def frame_signal(sig, win_size, hop_size):
    num_frames = 1 + (len(sig) - win_size) // hop_size
    shape = (num_frames, win_size)
    strides = (sig.strides[0] * hop_size, sig.strides[0])
    return np.lib.stride_tricks.as_strided(sig, shape=shape, strides=strides)

