import numpy as np
def add_gaussian_noise(img, mean=0, std=25):
    noise = np.random.normal(mean, std, img.shape)
    noisy_img = np.clip(img.astype(np.float32) + noise, 0, 255)
    return noisy_img.astype(np.uint8)

